# ----------------------------
# Parameters
# ----------------------------
BLOCK_SIZE = 512  # SD block size in bytes

# ----------------------------
# Convert pixels to a bytes array (little-endian u16)
# ----------------------------
bytes_array = bytearray()
for px in pixels:
    bytes_array += struct.pack("<H", px)  # 2 bytes per pixel

# ----------------------------
# Pad to multiple of 512 bytes
# ----------------------------
padding = (-len(bytes_array)) % BLOCK_SIZE
bytes_array += b'\x00' * padding

# ----------------------------
# Optional: split into SD blocks
# ----------------------------
blocks = [bytes_array[i:i+BLOCK_SIZE] for i in range(0, len(bytes_array), BLOCK_SIZE)]

# ----------------------------
# bytes_array now contains the full data ready to send
# blocks contains each 512-byte SD block
# ----------------------------
print("Total bytes:", len(bytes_array))
print("Blocks:", len(blocks))
# print blocks as a C array
for i, block in enumerate(blocks):
    print(', '.join(f'0x{b:02x}' for b in block))